std::vector<model::CecObservation> editor_observations(const ConfigurationV2& config){
    std::vector<model::CecObservation> out;
    for(const auto& c:config.components)for(const auto& name:c.record.qualified_names){model::CecObservation o;o.endpoint={name.port,static_cast<uint8_t>(name.port.side==model::Side::front?0:4)};o.osd_name=name.osd_name;o.device_type=name.port.side==model::Side::front?0:4;o.physical_address=name.port.side==model::Side::front?0:0x1000;o.owner_boot_id=id<model::BootId>(200);o.scan_id=id<model::ScanId>(201);o.local_sequence=1;out.push_back(o);}return out;
}
